/* Looks an interface up like ShardHostApi::query_interface does : the host says whether it offers it to this plugin, the table is the module's */
static ShardResult shard_wasm_query_interface(ShardStr id, uint32_t major, uint32_t minMinor, const void** out)
{
    uint32_t i;
    if (!out) return SHARD_E_INVALID_ARG;
    *out = 0;
    for (i = 0; i < sizeof(shard_wasm_interfaces) / sizeof(shard_wasm_interfaces[0]); ++i) {
        const ShardWasmInterface* entry = &shard_wasm_interfaces[i];
        uint64_t k = 0;
        if (entry->idSize != id.size) continue;
        while (k < id.size && entry->id[k] == id.data[k]) ++k;
        if (k != id.size) continue;
        {
            const ShardResult offered = shard_wasm_interface_offered(id, major, minMinor);
            if (offered == SHARD_OK) *out = entry->table;
            return offered;
        }
    }
    return SHARD_E_NOT_FOUND;
}

